WITH filtered AS (SELECT id, channel, ends_on, discount_pct, DATEDIFF(CURRENT_DATE(), ends_on) days_since_ends_on, DATEDIFF(CURRENT_DATE(), ends_on) days_since_ends_on_2 FROM promotions WHERE promo_code = 'SPRING10'), metrics AS (SELECT *, PERCENT_RANK() OVER (PARTITION BY channel ORDER BY discount_pct) discount_pct_percent_rank, LAG(days_since_ends_on, 1) OVER (ORDER BY days_since_ends_on_2, id) prev_days_since_ends_on, SUM(discount_pct) OVER (PARTITION BY channel ORDER BY days_since_ends_on_2, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_discount_pct FROM filtered), with_window AS (SELECT e.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct AS promotion_discount_pct FROM metrics e LEFT JOIN promotions pr ON COALESCE(e.channel, 'store') = pr.channel AND e.ends_on >= pr.starts_on AND e.ends_on <= DATE_ADD(pr.ends_on, 10)), attributed AS (SELECT a.*, pr.id AS promo_id_2, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct_2 FROM with_window a LEFT JOIN promotions pr ON a.channel = pr.channel AND a.ends_on >= pr.starts_on AND a.ends_on <= DATE_ADD(pr.ends_on, 3)), matched AS (SELECT a.*, pr.id AS promo_id_3, pr.promo_code AS promotion_promo_code_2, pr.discount_pct AS promotion_discount_pct_3 FROM attributed a LEFT JOIN promotions pr ON a.channel = pr.channel AND a.ends_on >= pr.starts_on AND a.ends_on < pr.ends_on + INTERVAL 30 DAYS), with_windows AS (SELECT *, LEAD(days_since_ends_on_2, 1) OVER w_recent next_days_since_ends_on_2, PERCENT_RANK() OVER (PARTITION BY promo_code ORDER BY promo_id_3 NULLS FIRST) promo_id_3_percent_rank, CUME_DIST() OVER w_ordered running_discount_pct_cume_dist FROM matched WINDOW w_recent AS (ORDER BY days_since_ends_on_2, id, promo_id, promo_id_2, promo_id_3), w_ordered AS (PARTITION BY promotion_promo_code ORDER BY running_discount_pct DESC NULLS LAST)), kept_keys AS (SELECT channel FROM with_windows EXCEPT SELECT channel FROM promotions WHERE ends_on <= '2023-03-04'), reconciled AS (SELECT s.* FROM with_windows s INNER JOIN kept_keys k ON s.channel = k.channel) SELECT *, RANK() OVER (PARTITION BY promo_code ORDER BY discount_pct_percent_rank DESC NULLS LAST) discount_pct_percent_rank_rank, PERCENT_RANK() OVER (PARTITION BY promotion_promo_code ORDER BY next_days_since_ends_on_2 DESC NULLS LAST) next_days_since_ends_on_2_percent_rank FROM reconciled
